const upsertStockLevel = `-- name: UpsertStockLevel :exec
INSERT INTO materials.stock_level (
    tenant_id, item_id, location_id, minimum, maximum, reorder_quantity,
    updated_at, updated_by
) VALUES (
    $1, $2, $3, $4, $5, $6,
    $7, $8
)
ON CONFLICT (tenant_id, item_id, location_id) DO UPDATE
SET minimum = EXCLUDED.minimum, maximum = EXCLUDED.maximum,
    reorder_quantity = EXCLUDED.reorder_quantity,
    updated_at = EXCLUDED.updated_at, updated_by = EXCLUDED.updated_by
`

type UpsertStockLevelParams struct {
	TenantID        uuid.UUID
	ItemID          uuid.UUID
	LocationID      string
	Minimum         int32
	Maximum         int32
	ReorderQuantity int32
	UpdatedAt       pgtype.Timestamptz
	UpdatedBy       string
}

func (q *Queries) UpsertStockLevel(ctx context.Context, arg UpsertStockLevelParams) error {
	_, err := q.db.Exec(ctx, upsertStockLevel,
		arg.TenantID,
		arg.ItemID,
		arg.LocationID,
		arg.Minimum,
		arg.Maximum,
		arg.ReorderQuantity,
		arg.UpdatedAt,
		arg.UpdatedBy,
	)
	return err
}
